let data,lang=new URLSearchParams(location.search).get('lang')==='zh'?'zh':'en',filter='all';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const url=(p='/')=>p+(lang==='zh'?'?lang=zh':'');
function art(type,large=false){const zh=lang==='zh';if(type==='hub')return `<div class="art hub ${large?'large':''}" aria-hidden="true"><span class="art-label">${zh?'数据连接':'CONNECTED DATA'}</span><div class="orbit o1"></div><div class="orbit o2"></div><div class="hub-core">${zh?'数据<br>平台':'DATA<br>HUB'}</div><span class="node n1">${zh?'来源':'Sources'}</span><span class="node n2">${zh?'质量':'Quality'}</span><span class="node n3">${zh?'决策':'Decisions'}</span><span class="node n4">${zh?'治理':'Governance'}</span><span class="art-foot">01 / ${zh?'连接 · 对齐 · 应用':'CONNECT · ALIGN · ACT'}</span></div>`;
if(type==='chart')return `<div class="art chart ${large?'large':''}" aria-hidden="true"><span class="art-label">${zh?'业务洞察':'BUSINESS INSIGHT'}</span><div class="chart-panel"><div class="chart-head"><span>${zh?'绩效概览':'Performance overview'}</span><span>↗</span></div><div class="bars">${[32,47,39,66,58,80,69,91].map((h,i)=>`<i style="height:${h}%;opacity:${.35+i*.08}"></i>`).join('')}</div><div class="chart-axis"><span>01</span><span>08</span></div></div><span class="art-foot">${zh?'模拟数据 · 仅作示意':'SIMULATED DATA · ILLUSTRATION'}</span></div>`;
return `<div class="art flow ${large?'large':''}" aria-hidden="true"><span class="art-label">${zh?'流程设计':'PROCESS DESIGN'}</span><div class="flow-line"><span>01 ${zh?'识别':'Identify'}</span><b>↓</b><span>02 ${zh?'评估':'Assess'}</span><b>↓</b><span class="final">03 ${zh?'行动':'Act'} <i>✓</i></span></div><span class="art-foot">03 / ${zh?'从流程到系统':'PROCESS INTO PRACTICE'}</span></div>`;}
function cards(){const t=data.profile[lang],ps=data.projects.filter(p=>filter==='all'||p.category===filter);$('#cards').innerHTML=ps.length?ps.map(p=>`<a class="project" href="${url('/work/'+p.id+'/')}">${art(p.art)}<div class="project-copy"><div class="meta">${t[p.category]} <span>↗</span></div><h3>${p[lang].title}</h3><p>${p[lang].desc}</p><div class="tags">${p[lang].tags.map(x=>`<span>${x}</span>`).join('')}</div></div></a>`).join(''):`<div class="empty">${t.noWork}</div>`;}
function contact(){const t=data.profile[lang];return `<section class="contact" id="contact"><div><span class="eyebrow">${t.nav[2]}</span><h2>${t.contactTitle}</h2><p>${t.contactText}</p></div><a class="contact-link" href="mailto:${esc(data.contact.email)}"><span>${t.email}</span><b>↗</b><small>${esc(data.contact.email)}</small></a></section>`;}
function render(){const t=data.profile[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('.skip').textContent=lang==='zh'?'跳至正文':'Skip to content';$('#header').innerHTML=`<a class="brand" href="${url('/')}"><span class="monogram">CL<span>・</span></span><span class="brand-name">CHONGHUA LI</span></a><nav aria-label="${lang==='zh'?'主导航':'Main navigation'}"><a href="${url('/')}#work">${t.nav[0]}</a><a href="${url('/about/')}">${t.nav[1]}</a><a href="${url('/')}#contact">${t.nav[2]}</a><div class="lang"><button data-lang="en" aria-pressed="${lang==='en'}">EN</button><span>/</span><button data-lang="zh" aria-pressed="${lang==='zh'}">中文</button></div></nav>`;
const path=location.pathname.replace(/\/+$/,'')||'/';
if(path==='/'){document.title='Chonghua Li — '+(lang==='zh'?'数据与数字化转型':'Data & Digital Transformation');$('#main').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow"><i class="dot"></i>${t.eyebrow}</span><h1>${t.headline}</h1><p class="intro">${t.intro}</p><div class="actions"><a class="button" href="#work">${t.explore} <span>↗</span></a><a class="text-link" href="${url('/about/')}">${t.about} <span>→</span></a></div></div><div class="hero-graphic" aria-hidden="true"><div class="graphic-top">${lang==='zh'?'思考与实践的交汇':'THE INTERSECTION'} <span>01 — 03</span></div><div class="rings"><div class="ring r1"></div><div class="ring r2"></div><div class="ring r3"></div><span class="ring-label l1">${lang==='zh'?'业务':'BUSINESS'}</span><span class="ring-label l2">${lang==='zh'?'技术':'TECHNOLOGY'}</span><span class="ring-label l3">${lang==='zh'?'交付':'DELIVERY'}</span><span class="center-star">✳</span></div><div class="graphic-bottom">${lang==='zh'?'连接思考与实践':'Connecting thinking & doing.'}<span>↗</span></div></div></section><div class="context-strip"><span>${lang==='zh'?'跨行业实践':'EXPERIENCE ACROSS'}</span><b>${lang==='zh'?'制造业':'Manufacturing'}</b><i>·</i><b>${lang==='zh'?'基础设施':'Infrastructure'}</b><i>·</i><b>${lang==='zh'?'企业数据':'Enterprise data'}</b></div><section class="work section" id="work"><div class="section-heading"><div><span class="eyebrow">01 / ${t.nav[0]}</span><h2>${t.selected}</h2></div><p>${t.selectedsub}</p></div><div class="filters" role="group" aria-label="${lang==='zh'?'作品类型':'Project categories'}">${['all','coding','data','solution'].map(c=>`<button data-filter="${c}" aria-pressed="${filter===c}">${t[c]}</button>`).join('')}</div><div class="cards" id="cards"></div></section><section class="approach section"><div><span class="eyebrow">02 / ${t.approach}</span><h2>${t.approachTitle}</h2></div><div class="steps">${t.steps.map(s=>`<article><span>${s[0]}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div></article>`).join('')}</div></section>${contact()}`;cards();}
else if(path==='/about'){$('#main').innerHTML=`<section class="about-intro section"><span class="eyebrow">${t.nav[1]} / CHONGHUA LI</span><h1>${t.aboutTitle}</h1><p class="intro">${t.bio}</p></section><section class="experience section"><h2>${t.experience}</h2><div>${data.experience.map(e=>`<article class="job"><span class="date">${e[1]}</span><div><h3>${e[0]}</h3><b>${e[2][lang]}</b><p>${e[3][lang]}</p></div></article>`).join('')}</div></section><section class="education section"><h2>${t.education}</h2><div><article><span class="date">2021 — 2022</span><h3>National University of Singapore</h3><p>${lang==='zh'?'科技硕士 · 商业分析':'Master of Technology · Business Analytics'}</p></article><article><span class="date">2013 — 2017</span><h3>${lang==='zh'?'华东理工大学':'East China University of Science and Technology'}</h3><p>${lang==='zh'?'工学学士 · 机械自动化':'Bachelor of Engineering · Mechanical Automation'}</p></article></div></section><section class="skill-section section"><h2>${t.skills}</h2><div class="tags">${(lang==='zh'?['数据分析','数字化战略','项目交付','Python / SQL','Power BI / Tableau','Azure','工作流设计']:['Data analytics','Digital strategy','Project delivery','Python / SQL','Power BI / Tableau','Azure','Workflow design']).map(x=>`<span>${x}</span>`).join('')}</div></section>${contact()}`;document.title=t.nav[1]+' — Chonghua Li';}
else {const p=data.projects.find(x=>path==='/work/'+x.id);if(!p){$('#main').innerHTML=`<section class="section"><span class="eyebrow">404</span><h1>${lang==='zh'?'找不到此页面。':'Page not found.'}</h1><a class="button" href="${url('/')}">${lang==='zh'?'返回首页':'Back to home'} →</a></section>`;}else{const c=p[lang];document.title=c.subtitle+' — Chonghua Li';$('#main').innerHTML=`<section class="detail-intro section"><a class="text-link" href="${url('/')}#work">← ${t.back}</a><div class="detail-heading"><span class="eyebrow">${t[p.category]} / ${c.subtitle}</span><h1>${c.title}</h1><p class="intro">${c.desc}</p><div class="tags">${c.tags.map(x=>`<span>${x}</span>`).join('')}</div></div>${art(p.art,true)}<p class="caption">${t.illustration}</p></section><section class="case-content section">${['context','role','method','outcome'].map((k,i)=>`<article><span class="eyebrow">0${i+1} / ${t[k]}</span><p>${c[k]}</p></article>`).join('')}</section>${p.art==='chart'?`<section class="demo section"><div><span class="eyebrow">${lang==='zh'?'交互示例':'INTERACTIVE'} / ${t.data}</span><h2>${t.demo}</h2><p>${t.demoDesc}</p><small>${t.demoNote}</small></div><div class="calculator"><label>${t.demand}<output id="demandVal">1,000</output><input id="demand" type="range" min="100" max="3000" step="100" value="1000"></label><label>${t.inventory}<output id="inventoryVal">3,000</output><input id="inventory" type="range" min="0" max="12000" step="100" value="3000"></label><div class="calc-result"><span>${t.months}</span><output id="cover" aria-live="polite">3.0</output></div></div></section>`:''}<aside class="case-note"><b>${t.note}</b><p>${c.note}</p></aside>${contact()}`;}}
$('#footer').innerHTML=`<a class="monogram" href="${url('/')}">CL<span>・</span></a><span>© ${new Date().getFullYear()} Chonghua Li</span><span>${t.footer}</span><a href="#header" aria-label="${lang==='zh'?'回到顶部':'Back to top'}">↑</a>`;
for(const b of document.querySelectorAll('[data-lang]'))b.onclick=()=>{const y=scrollY;lang=b.dataset.lang;const u=new URL(location.href);lang==='zh'?u.searchParams.set('lang','zh'):u.searchParams.delete('lang');history.replaceState({},'',u);render();scrollTo({top:y,behavior:'instant'});};
for(const b of document.querySelectorAll('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));cards();};
for(const input of document.querySelectorAll('.calculator input'))input.oninput=()=>{$('#demandVal').textContent=Number($('#demand').value).toLocaleString();$('#inventoryVal').textContent=Number($('#inventory').value).toLocaleString();$('#cover').textContent=(Number($('#inventory').value)/Number($('#demand').value)).toFixed(1);};
}
fetch('/content.json').then(r=>{if(!r.ok)throw Error('content');return r.json()}).then(d=>{data=d;render();if(location.hash)document.getElementById(location.hash.slice(1))?.scrollIntoView();}).catch(()=>{$('#main').textContent='Unable to load this page. Please refresh. / 页面加载失败，请刷新。';});
